import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import './Auth.css';

function Register() {
  const [formData, setFormData] = useState({
    fullName: '',
    username: '',
    idNumber: '',
    accountNumber: '',
    password: '',
    confirmPassword: ''
  });
  const [errors, setErrors] = useState([]);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const validatePassword = (password) => {
    // Check each requirement separately for better error messages
    const hasLowercase = /[a-z]/.test(password);
    const hasUppercase = /[A-Z]/.test(password);
    const hasNumber = /\d/.test(password);
    const hasSpecial = /[@$!%*?&]/.test(password);
    const isLongEnough = password.length >= 8;
    const onlyAllowedChars = /^[A-Za-z\d@$!%*?&]+$/.test(password);

    console.log('Password validation:', {
      hasLowercase,
      hasUppercase,
      hasNumber,
      hasSpecial,
      isLongEnough,
      onlyAllowedChars,
      passwordLength: password.length
    });

    return hasLowercase && hasUppercase && hasNumber && hasSpecial && isLongEnough && onlyAllowedChars;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrors([]);
    setSuccess('');

    console.log('Form submitted');

    // Client-side validation
    const validationErrors = [];

    if (formData.password !== formData.confirmPassword) {
      validationErrors.push('Passwords do not match');
    }

    if (!validatePassword(formData.password)) {
      validationErrors.push('Password must be at least 8 characters with uppercase, lowercase, number and special character (@$!%*?&)');
    }

    if (validationErrors.length > 0) {
      console.log('Validation errors:', validationErrors);
      setErrors(validationErrors);
      return;
    }

    setLoading(true);

    try {
      const { confirmPassword, ...dataToSend } = formData;
      console.log('Sending registration request...');

      const response = await api.post('/auth/register', dataToSend);
      console.log('Registration successful:', response.data);

      setSuccess('Registration successful! Redirecting to login...');
      setTimeout(() => navigate('/login'), 2000);
    } catch (err) {
      console.error('Registration error:', err);
      console.error('Error response:', err.response?.data);

      const errorMessages = err.response?.data?.errors || 
                          [err.response?.data?.error] || 
                          ['Registration failed. Please try again.'];
      setErrors(errorMessages);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <div className="auth-card">
        <h2>Customer Registration</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Full Name</label>
            <input
              type="text"
              name="fullName"
              value={formData.fullName}
              onChange={handleChange}
              required
              placeholder="e.g., John Doe"
            />
          </div>

          <div className="form-group">
            <label>Username</label>
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleChange}
              required
              placeholder="e.g., johndoe"
            />
          </div>

          <div className="form-group">
            <label>ID Number (13 digits)</label>
            <input
              type="text"
              name="idNumber"
              value={formData.idNumber}
              onChange={handleChange}
              required
              maxLength="13"
              placeholder="e.g., 9001010001088"
            />
          </div>

          <div className="form-group">
            <label>Account Number (10-16 digits)</label>
            <input
              type="text"
              name="accountNumber"
              value={formData.accountNumber}
              onChange={handleChange}
              required
              placeholder="e.g., 1234567890"
            />
          </div>

          <div className="form-group">
            <label>Password</label>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
              placeholder="Example: Password1!"
            />
            <small style={{color: '#666', fontSize: '12px', marginTop: '5px', display: 'block'}}>
              Must contain: uppercase, lowercase, number, and one of @$!%*?&
            </small>
          </div>

          <div className="form-group">
            <label>Confirm Password</label>
            <input
              type="password"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              required
              placeholder="Re-enter your password"
            />
          </div>

          {errors.length > 0 && (
            <div className="error-message">
              {errors.map((err, idx) => <div key={idx}>{err}</div>)}
            </div>
          )}

          {success && <div className="success-message">{success}</div>}

          <button type="submit" disabled={loading} className="btn-primary">
            {loading ? 'Registering...' : 'Register'}
          </button>
        </form>

        <p className="auth-link">
          Already have an account? <a href="/login">Login here</a>
        </p>
      </div>
    </div>
  );
}

export default Register;
